class Solution {
public:
    vector<int> decimalRepresentation(int n) {
        vector<int> res;
        long long p = 1;
        while (n > 0) {
            int d = n % 10;
            if (d) res.push_back(d * p);
            n /= 10;
            p *= 10;
        }
        reverse(res.begin(), res.end());
        return res;
    }
};

