class Solution {
    public int[] decimalRepresentation(int n) {
        java.util.List<Integer> tmp = new java.util.ArrayList<>();
        long p = 1;
        while (n > 0) {
            int d = n % 10;
            if (d != 0) tmp.add((int)(d * p));
            n /= 10;
            p *= 10;
        }
        int[] res = new int[tmp.size()];
        for (int i = 0; i < res.length; i++) res[i] = tmp.get(res.length - 1 - i);
        return res;
    }
}

