class Solution {
    public int[] decimalRepresentation(int n) {
        String s = Integer.toString(n);
        int L = s.length();
        java.util.List<Integer> tmp = new java.util.ArrayList<>();
        for (int i = 0; i < L; i++)
            if (s.charAt(i) != '0') tmp.add((s.charAt(i)-'0') * (int)Math.pow(10, L-1-i));
        int[] res = new int[tmp.size()];
        for (int i = 0; i < res.length; i++) res[i] = tmp.get(i);
        return res;
    }
}

